def find_devs_with_openbsd(criteria=None, oformat='device',
                           tag=None, no_cache=False, path=None):
    out, _err = subp.subp(['sysctl', '-n', 'hw.disknames'], rcs=[0])
    devlist = []
    for entry in out.split(','):
        if not entry.endswith(':'):
            continue
