                return IRnode.from_list(["chainid"], typ=UINT256_T)
        else:
            sub = Expr(self.expr.value, self.context).ir_node
            if isinstance(sub.typ, InterfaceT):
                assert self.expr.attr == "address"
                sub.typ = typ
