        varinfo = node.target._metadata["varinfo"]
        varinfo.set_position(StorageSlot(storage_slot))
        type_ = varinfo.typ
        ret[node.target.id] = {"type": str(type_), "slot": storage_slot}
        storage_slot += math.ceil(type_.size_in_bytes / 32)
    return ret
