    def _load_regex_engine(self, yamlconfig):
        engine = yamlconfig.get('engine', 're')
        re_module = None
        if not engine in ['re', 'regex']:
            raise PystemonConfigException("only 're' or 'regex' supported, not '{0}'".format(engine))
        try:
